/** Expands to fully qualified locale indices of region */
#define REGION(cc, rev, loc_2, loc_5, loc_HT_2, loc_HT_5, flags) \
    {{cc, (unsigned char)(0xFF & rev)},  \
     {(unsigned char)(0xFF & LOCALE_2G_IDX_##loc_2), \
      (unsigned char)(0xFF & LOCALE_5G_IDX_##loc_5), \
      (unsigned char)(0xFF & LOCALE_2G_HT_IDX_##loc_HT_2), \
      (unsigned char)(0xFF & LOCALE_5G_HT_IDX_##loc_HT_5)}, \
     (unsigned char)(((LOCALE_2G_IDX_##loc_2>>8)&0x03)+((LOCALE_5G_IDX_##loc_5>>6) & 0x0C) + \
         ((LOCALE_2G_HT_IDX_##loc_HT_2>>4)&0x30) + ((LOCALE_5G_HT_IDX_##loc_HT_5>>2)&0xC0)), \
     (unsigned char)(0xFF & (flags))}

